-- Bosses the Library names without their instance (Tier 1 and Tier 2 sets).
local BOSS_PLACE = {}
for _, boss in ipairs({ "Lucifron", "Magmadar", "Gehennas", "Garr", "Shazzrah", "Baron Geddon", "Sulfuron Harbinger",
    "Golemagg the Incinerator", "Majordomo Executus", "Ragnaros" }) do BOSS_PLACE[boss] = "Molten Core" end
for _, boss in ipairs({ "Razorgore the Untamed", "Vaelastrasz the Corrupt", "Broodlord Lashlayer",
    "Firemaw, Ebonroc or Flamegor", "Chromaggus", "Nefarian" }) do BOSS_PLACE[boss] = "Blackwing Lair" end
BOSS_PLACE["Onyxia"] = "Onyxia's Lair"

-- Turn a Library piece's source wording ("Garr", "Gyth (Upper Blackrock Spire)",
-- "the quest 'X'", "Molten Core trash", "PvP rank 13") into a source.
local function FromLibrary(text)
    local quest = text:match("^the quest '(.+)'$")
    if quest then return Quest("Complete '" .. quest .. "' for %s", "Quest — " .. quest) end
    if text:match("^PvP rank") then return { step = "Earn %s at " .. text, label = text } end
    local who, place = text:match("^(.-) %((.+)%)$")
    if who then
        if who:match("^random dungeon trash") or who:match("trash") then return { step = "Loot %s from " .. text, label = text, place = place } end
        return Loot(who, place)
    end
    local raid = text:match("^(.-) trash$")
    if raid then return { step = "Loot %s from trash in " .. raid, label = text, place = raid } end
    if BOSS_PLACE[text] then return Loot(text, BOSS_PLACE[text]) end
    return { step = "Loot %s from " .. text, label = text }
end

local harvested
local function Harvest()
    harvested = {}
    local tier3 = FGT.armorCollections and FGT.armorCollections.tier3
    for _, goal in ipairs(FGT.goals or {}) do
        for _, section in ipairs(goal.sections or {}) do
            for _, piece in ipairs(section.pieces or {}) do
                local ids = piece.auto and piece.auto.item
                local text = piece.text
                if ids and text then
                    local source = text:match("^Collect .- from (.+)%.$")
                    local rank = text:match("^Collect .- at (PvP rank .+)%.$")
                    source = rank or source
                    if source then
                        local entry = FromLibrary(source)
                        for _, id in ipairs(type(ids) == "table" and ids or { ids }) do
                            if not harvested[id] then harvested[id] = entry end
                        end
                    end
                end
            end
        end
    end
    -- Tier 3 is a turn-in at Light's Hope Chapel; the rings come from Kel'Thuzad.
    for _, section in ipairs(tier3 and tier3.sections or {}) do
        for _, piece in ipairs(section.pieces or {}) do
            local id = piece.auto and piece.auto.item
            if type(id) == "number" and not harvested[id] then
                harvested[id] = { step = "Obtain %s from a Tier 3 turn-in at Light's Hope Chapel", label = "Tier 3 turn-in — Light's Hope Chapel" }
            end
        end
    end
    for id = 23059, 23067 do harvested[id] = Loot("Kel'Thuzad", "Naxxramas") end
end

function C.Source(item)
    if not item then return nil end
    if curated[item.id] then return curated[item.id] end
    if not harvested then Harvest() end
    if harvested[item.id] then return harvested[item.id] end
    -- The game's own tables say when an item is a PvP reward.
    local rank = item.note and item.note:match("^Requires (PvP rank %d+)$")
    if rank then return { step = "Earn %s at " .. rank, label = rank, pvp = true } end
end

-- Dungeon and raid names the planner tags itself (the ones the guides do not auto-link).
local function TagPlaces(text)
    if not (FGT.LocationTag and FGT.DUNGEONS) then return text end
    for _, entrance in ipairs(FGT.DUNGEONS) do
        if entrance.manual and text:find(entrance.name, 1, true) and not text:find("|Hfgtentrance:", 1, true) then
            local first, last = text:find(entrance.name, 1, true)
            text = text:sub(1, first - 1) .. FGT.LocationTag(entrance.id, entrance.name) .. text:sub(last + 1)
        end
    end
    return text
end

-- The dungeon or raid entrance (an FGT.DUNGEONS entry) for a place named in a source, if there is one.
function C.EntranceFor(place)
    local best
    for _, entrance in ipairs(FGT.DUNGEONS or {}) do
        if entrance.map and entrance.x then
            local names = { entrance.name }
            for _, alias in ipairs(entrance.alias or {}) do names[#names + 1] = alias end
            for _, name in ipairs(names) do
                if place:find(name, 1, true) and (not best or #name > best.len) then best = { entrance = entrance, len = #name } end
            end
        end
    end
    return best and best.entrance
end

-- The short line under an item in a list: where it comes from, or what the game says it needs.
function C.SourceLabel(item)
    local source = C.Source(item)
    if source then return source.label end
    return item.note or "Source unknown"
end

-- The goal step and an optional tip for collecting an item.
function C.Acquisition(item)
    local source = C.Source(item)
    local text, advice
    if source then
        text, advice = source.step:format(item.name), source.advice
    else
        text = "Collect " .. item.name .. " (Source unknown)"
    end
    if item.note and not text:find(item.note, 1, true) and not (source and source.label:find(item.note, 1, true))
        and not (advice and advice:find(item.note, 1, true)) then
        advice = advice and (advice .. " " .. item.note .. ".") or (item.note .. ".")
    end
    return TagPlaces(text), advice
end

-- Is this item known to the Forever client? nil on Classic Era.
function C.ForeverStatus(item)
    if not FGT.isForever then return nil end
    if item.forever >= 2 then return "new" end
    if item.forever == 0 then return "hidden" end
    return "known"
end

